server {
    listen 80;
    server_name _;
    root /usr/share/nginx/html;
    index index.html;
    add_header X-Content-Type-Options nosniff;
    add_header Referrer-Policy same-origin;
    location = /health { default_type application/json; return 200 '{"status":"ok"}'; }
    location /api/notifications { proxy_pass http://notification-worker:8080; proxy_read_timeout 35s; }
    location /api/ { proxy_pass http://order-service:8080; proxy_read_timeout 35s; }
    location / { try_files $uri $uri/ /index.html; }
}

export class ApiError extends Error {
  constructor(message:string, public status:number, public body:unknown) {super(message);}
}
export async function request<T>(path:string, options:RequestInit={}):Promise<T> {
  const response=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers},signal:AbortSignal.timeout(30000)});
  const text=await response.text();
  let body:unknown;
  try {body=text ? JSON.parse(text):null;} catch {throw new ApiError('Service returned an unreadable response. Check the services and retry.',response.status,null);}
  if (!response.ok) {
    const error=body as {message?:string;detail?:string;failureReason?:string};
    throw new ApiError(error?.message || error?.failureReason || (typeof error?.detail==='string' ? error.detail : '') || `Request failed (${response.status}).`,response.status,body);
  }
  return body as T;
}

import React, {useEffect,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {cartSummary,validateCheckout,checkoutAttempt,money,type Product,type Checkout,type Attempt,type Order,type Notification} from './domain';
import {ApiError,request} from './api';
import './styles.css';

const STORAGE='commercelens.checkout.v1';
function savedAttempt():Attempt|null {try {const value=JSON.parse(sessionStorage.getItem(STORAGE)||'null'); return value?.key && value?.body?.items ? value : null;} catch {return null;}}
function Status({value}:{value:string}) {return <span className={`status status-${value.toLowerCase()}`}>{value.replaceAll('_',' ')}</span>;}
function App() {
  const [tab,setTab]=useState<'shop'|'operations'>('shop');
  const [products,setProducts]=useState<Product[]>([]),[orders,setOrders]=useState<Order[]>([]),[notifications,setNotifications]=useState<Notification[]>([]);
  const [cart,setCart]=useState<Record<string,number>>({}),[email,setEmail]=useState(''),[postal,setPostal]=useState('');
  const [payment,setPayment]=useState<Checkout['paymentScenario']>('success'),[shipping,setShipping]=useState<Checkout['shippingScenario']>('success');
  const [attempt,setAttempt]=useState<Attempt|null>(savedAttempt),[selected,setSelected]=useState<Order|null>(null);
  const [busy,setBusy]=useState(false),[loading,setLoading]=useState(true),[error,setError]=useState(''),[notice,setNotice]=useState(''),[loadErrors,setLoadErrors]=useState<string[]>([]);
  async function refresh() {
    setLoading(true);
    const result=await Promise.allSettled([request<Product[]>('/api/products'),request<Order[]>('/api/orders'),request<Notification[]>('/api/notifications')]);
    const errors:string[]=[];
    if(result[0].status==='fulfilled')setProducts(result[0].value);else errors.push('Catalog unavailable. Start inventory and order services.');
    if(result[1].status==='fulfilled')setOrders(result[1].value);else errors.push('Order history unavailable.');
    if(result[2].status==='fulfilled')setNotifications(result[2].value);else errors.push('Notification worker unavailable. Orders can still be placed.');
    setLoadErrors(errors);setLoading(false);
  }
  useEffect(()=>{void refresh();},[]);
  const summary=cartSummary(products,cart);
  const pendingTotal=attempt ? cartSummary(products,Object.fromEntries(attempt.body.items.map(i=>[i.sku,i.quantity]))) : summary;
  function quantity(sku:string, n:number) {setCart(old=>{const next={...old}; if(n>0)next[sku]=n;else delete next[sku];return next;});}
  async function submit(event:React.FormEvent) {
    event.preventDefault();setError('');setNotice('');
    const body:Checkout={customerEmail:email.trim(),postalCode:postal.trim(),items:Object.entries(cart).map(([sku,quantity])=>({sku,quantity})),paymentScenario:payment,shippingScenario:shipping};
    if(!attempt){const invalid=validateCheckout(body,products);if(invalid){setError(invalid);return;}}
    const next=checkoutAttempt(body,attempt);
    try {sessionStorage.setItem(STORAGE,JSON.stringify(next));} catch {setError('Browser storage is unavailable. Enable session storage before checkout so retries remain safe.');return;}
    setAttempt(next);setBusy(true);
    try {
      const order=await request<Order>('/api/orders',{method:'POST',headers:{'Idempotency-Key':next.key},body:JSON.stringify(next.body)});
      setSelected(order);setNotice(`Order ${order.id} — ${order.status.replaceAll('_',' ')}.`);
    } catch(e) {
      const payload=e instanceof ApiError ? e.body as {order?:Order;id?:string;status?:string}:null;
      if(payload?.order)setSelected(payload.order);else if(payload?.id&&payload.status)setSelected(payload as Order);
      setError(e instanceof ApiError ? e.message : 'Connection interrupted. The order outcome may be unknown. Retry this same checkout to recover its status.');
    } finally {setBusy(false);await refresh();}
  }
  function newOrder() {
    if(attempt && !window.confirm('Start a different order? Check order history first: a previous payment may still be pending. Retrying the existing checkout is safer if its outcome is unknown.'))return;
    sessionStorage.removeItem(STORAGE);setAttempt(null);setCart({});setError('');setNotice('');setSelected(null);
  }
  async function detail(id:string) {try {setSelected(await request<Order>(`/api/orders/${encodeURIComponent(id)}`));setError('');}catch(e){setError(e instanceof Error?e.message:'Unable to load order.');}}
  return <div className="app">
    <header><a className="brand" href="/" aria-label="CommerceLens home"><span className="brand-mark">C<span>↗</span></span><span>Commerce<span className="light">Lens</span></span></a><div className="header-right"><span className="environment"><i/> LOCAL SANDBOX</span><span className="avatar">CL</span></div></header>
    <nav aria-label="Main navigation"><button className={tab==='shop'?'active':''} onClick={()=>setTab('shop')}>Storefront</button><button className={tab==='operations'?'active':''} onClick={()=>setTab('operations')}>Operations <span className="count">{orders.length}</span></button><span className="nav-note">One checkout. Connected services.</span></nav>
    <main>
      <section className="hero"><div><p className="eyebrow">COMMERCE, UNDER THE LENS</p><h1>{tab==='shop'?'Small essentials. Big connections.':'Every order tells a story.'}</h1><p>{tab==='shop'?'A real checkout journey through inventory, payments, shipping, and notifications.':'Follow orders across services and inspect delivery outcomes.'}</p></div><div className="hero-number"><span>06</span><small>independent services</small></div></section>
      <div className="mock-banner"><span>◈</span><p><strong>Demo provider mode.</strong> Payment, shipping, and email use local HTTP mocks. No real charge or message is sent.</p></div>
      {loadErrors.map(message=><div className="alert warning" role="status" key={message}>{message}</div>)}
      {error&&<div className="alert error" role="alert">{error}</div>}{notice&&<div className="alert success" role="status">{notice}</div>}
      {tab==='shop'?<div className="shop-layout"><section><div className="section-heading"><div><p className="eyebrow">THE COLLECTION</p><h2>Built for the curious.</h2></div><button className="text-button" onClick={()=>void refresh()} disabled={loading}>{loading?'Loading…':'↻ Refresh stock'}</button></div>
        <div className="products">{products.map((p,i)=><article className="product" key={p.sku}><div className={`product-art art-${i%3}`} aria-hidden="true"><span className="art-label">COMMERCE / ESSENTIALS</span><div className={`object object-${i%3}`}>{i%3===0?<><span>AGENTIC<br/>SYSTEMS</span><small>A FIELD GUIDE</small></>:i%3===1?<><b>⌘</b><small>MAKE SOMETHING</small></>:<b>C↗</b>}</div><span className="product-index">0{i+1}</span></div><div className="product-info"><small>{p.sku} · {p.available} available</small><h3>{p.name}</h3><div className="product-bottom"><strong>{money(p.priceCents)}</strong><button className="add-button" disabled={!!attempt||p.available<=0||(cart[p.sku]||0)>=p.available} onClick={()=>quantity(p.sku,(cart[p.sku]||0)+1)} aria-label={`Add ${p.name} to cart`}>+ Add{cart[p.sku]?` (${cart[p.sku]})`:''}</button></div></div></article>)}</div>
        {!loading&&!products.length&&<div className="empty">No products loaded. Start the backend services, then refresh.</div>}
        <div className="journey"><p className="eyebrow">BEHIND YOUR CHECKOUT</p><div><span>Reserve stock</span><b>→</b><span>Authorize payment</span><b>→</b><span>Create shipment</span><b>→</b><span>Send confirmation</span></div></div>
      </section><aside className="checkout"><div className="section-heading"><h2>Your checkout</h2><span className="count">{pendingTotal.count}</span></div>
        {attempt?<div className="attempt-note"><strong>Checkout saved</strong><p>{attempt.body.customerEmail} · {attempt.body.postalCode}</p><p>Retries reuse the same request and payment key, including after a page refresh.</p></div>:<div className="cart-lines">{products.filter(p=>cart[p.sku]).map(p=><div className="cart-line" key={p.sku}><div><strong>{p.name}</strong><small>{money(p.priceCents)} each</small></div><input aria-label={`Quantity for ${p.name}`} type="number" min="0" max={p.available} value={cart[p.sku]} onChange={e=>quantity(p.sku,Math.max(0,Math.floor(Number(e.target.value)||0)))}/></div>)}{!summary.count&&<p className="muted">Your next idea starts with something small. Add an essential to begin.</p>}</div>}
        <form onSubmit={submit}><fieldset disabled={busy||!!attempt}><label>Email address<input type="email" placeholder="you@example.com" value={email} onChange={e=>setEmail(e.target.value)} required={!attempt}/></label><label>Postal code<input placeholder="10001" maxLength={20} value={postal} onChange={e=>setPostal(e.target.value)} required={!attempt}/></label><details className="scenarios"><summary>Test a service scenario</summary><label>Payment provider<select value={payment} onChange={e=>setPayment(e.target.value as Checkout['paymentScenario'])}><option value="success">Authorization succeeds</option><option value="decline">Payment declined</option><option value="timeout">Provider timeout</option></select></label><label>Shipping provider<select value={shipping} onChange={e=>setShipping(e.target.value as Checkout['shippingScenario'])}><option value="success">Shipment created</option><option value="failure">Provider failure</option></select></label><p>Use an email containing <code>fail-email</code> to test notification retries.</p></details></fieldset>
        <div className="totals"><div><span>Subtotal estimate</span><span>{money(pendingTotal.subtotalCents)}</span></div><div><span>Shipping</span><span>{money(pendingTotal.shippingCents)}</span></div><div className="grand-total"><strong>Total estimate</strong><strong>{money(pendingTotal.totalCents)}</strong></div></div><p className="fine-print">Final price and stock are validated by the services.</p><button className="primary" type="submit" disabled={busy||(!attempt&&!summary.count)}>{busy?'Processing checkout…':attempt?'Retry / recover this order':'Place demo order'} <span>↗</span></button>{attempt&&<button className="text-button new-order" type="button" disabled={busy} onClick={newOrder}>Start a new order</button>}</form>
      </aside></div>:<section><div className="metrics"><div><small>Orders recorded</small><strong>{orders.length}</strong></div><div><small>Confirmed</small><strong>{orders.filter(o=>o.status.toLowerCase()==='confirmed').length}</strong></div><div><small>Needs attention</small><strong>{orders.filter(o=>o.status.toLowerCase()!=='confirmed').length}</strong></div><div><small>Notification records</small><strong>{notifications.length}</strong></div></div><div className="section-heading"><h2>Order activity</h2><button className="text-button" disabled={loading} onClick={()=>void refresh()}>{loading?'Refreshing…':'↻ Refresh activity'}</button></div><div className="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Status</th><th>Total</th><th>Created</th><th/></tr></thead><tbody>{orders.map(o=><tr key={o.id}><td><code>{o.id.slice(0,8)}</code></td><td>{o.customerEmail}</td><td><Status value={o.status}/></td><td>{money(o.totalCents)}</td><td>{new Date(o.createdAt).toLocaleString()}</td><td><button className="text-button" onClick={()=>void detail(o.id)}>Details ↗</button></td></tr>)}</tbody></table>{!orders.length&&<div className="empty">No orders yet. Place a demo order in the storefront.</div>}</div><h2 className="notifications-title">Notification delivery</h2><div className="notification-list">{notifications.map(n=><article key={n.eventId}><div><code>{n.orderId.slice(0,8)}</code><Status value={n.status}/></div><p>{n.attempts} delivery attempt{n.attempts===1?'':'s'}</p>{n.lastError&&<p className="failure">{n.lastError}</p>}</article>)}{!notifications.length&&<p className="muted">Delivery records appear after confirmed orders are consumed. Refresh to check progress.</p>}</div></section>}
      {selected&&<section className="order-detail" aria-label="Selected order"><div className="section-heading"><div><p className="eyebrow">ORDER DETAILS</p><h2>{selected.id}</h2></div><button className="text-button" onClick={()=>setSelected(null)}>Close</button></div><Status value={selected.status}/><div className="detail-grid"><p><small>Customer</small>{selected.customerEmail}</p><p><small>Total</small>{money(selected.totalCents)}</p><p><small>Tracking</small>{selected.trackingNumber||'Not available'}</p><p><small>Payment</small>{selected.paymentId||'Not available'}</p></div>{selected.failureReason&&<p className="failure">{selected.failureReason}</p>}<ul>{selected.items?.map(i=><li key={i.sku}>{i.name||i.sku} × {i.quantity}</li>)}</ul></section>}
      <footer><span>CommerceLens <span className="muted">/ Connected commerce, made visible.</span></span><span>Application assistant · planned next</span></footer>
    </main>
  </div>;
}
createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>);

package com.commercelens.orders;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import java.net.URI;
import java.net.http.*;
import java.time.Duration;
import java.util.*;

@Component
public class RemoteServices implements Checkout.Ports {
 private final String inventory,payment,shipping;private final ObjectMapper json;private final OrderStore store;
 private final HttpClient client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build();
 public RemoteServices(@Value("${inventory.url}")String inventory,@Value("${payment.url}")String payment,@Value("${shipping.url}")String shipping,ObjectMapper json,OrderStore store){this.inventory=inventory;this.payment=payment;this.shipping=shipping;this.json=json;this.store=store;}
 private JsonNode request(String method,String url,Object body){
  try{
   var builder=HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(8)).header("Content-Type","application/json");
   if(body==null)builder.GET();else builder.method(method,HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body)));
   var response=client.send(builder.build(),HttpResponse.BodyHandlers.ofString());
   if(response.statusCode()<200||response.statusCode()>=300){String message="upstream returned HTTP "+response.statusCode();try{JsonNode error=json.readTree(response.body());message=error.path("message").asText(error.path("detail").asText(message));}catch(Exception ignored){}throw new Checkout.RemoteFailure(response.statusCode(),message);}
   return json.readTree(response.body());
  }catch(Checkout.RemoteFailure e){throw e;}catch(Exception e){if(e instanceof InterruptedException)Thread.currentThread().interrupt();throw new Checkout.RemoteFailure(504,"upstream response unavailable; outcome may be uncertain");}
 }
 public JsonNode products(){return request("GET",inventory+"/api/products",null);}
 public Checkout.Reservation reserve(String id,Checkout.Request req){var result=request("POST",inventory+"/api/reservations",Map.of("orderId",id,"items",req.items()));var items=json.convertValue(result.path("items"),new TypeReference<List<Map<String,Object>>>(){});long subtotal=result.path("subtotalCents").asLong(-1);if(subtotal<0||items==null)throw new Checkout.RemoteFailure(502,"invalid inventory response");return new Checkout.Reservation(items,subtotal);}
 public String pay(String id,long cents,String scenario){return required(request("POST",payment+"/api/payments",Map.of("orderId",id,"amountCents",cents,"currency","USD","scenario",scenario)),"paymentId");}
 public String ship(String id,String postal,String scenario){return required(request("POST",shipping+"/api/shipments",Map.of("orderId",id,"postalCode",postal,"scenario",scenario)),"trackingNumber");}
 private String required(JsonNode body,String key){String value=body.path(key).asText();if(value.isBlank())throw new Checkout.RemoteFailure(504,"invalid provider response; outcome uncertain");return value;}
 public void release(String id){request("POST",inventory+"/api/reservations/"+id+"/release",Map.of());}
 public void refund(String paymentId,String id){request("POST",payment+"/api/payments/"+paymentId+"/refund",Map.of("orderId",id));}
 public void checkpoint(Checkout.Order order){store.checkpoint(order);}
}

package com.commercelens.orders;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;

@Repository
public class OrderStore {
 private final JdbcTemplate jdbc;private final ObjectMapper json;
 public OrderStore(JdbcTemplate jdbc,ObjectMapper json){this.jdbc=jdbc;this.json=json;}
 String encode(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}
 Checkout.Order decode(String value,int status){try{var order=json.readValue(value,Checkout.Order.class);order.httpStatus=status;return order;}catch(Exception e){throw new IllegalStateException(e);}}
 public boolean create(Checkout.Order order,String key,String hash){return jdbc.update("INSERT INTO orders(id,idempotency_key,request_hash,body) VALUES(?,?,?,?::jsonb) ON CONFLICT(idempotency_key) DO NOTHING",order.id,key,hash,encode(order))==1;}
 public Existing byKey(String key){return jdbc.queryForObject("SELECT request_hash,body::text,http_status FROM orders WHERE idempotency_key=?",(r,n)->new Existing(r.getString(1),decode(r.getString(2),r.getInt(3))),key);}
 public record Existing(String hash,Checkout.Order order){}
 public Optional<Checkout.Order> get(String id){return jdbc.query("SELECT body::text,http_status FROM orders WHERE id=?",(r,n)->decode(r.getString(1),r.getInt(2)),id).stream().findFirst();}
 public List<Checkout.Order> list(){return jdbc.query("SELECT body::text,http_status FROM orders ORDER BY created_at DESC LIMIT 200",(r,n)->decode(r.getString(1),r.getInt(2)));}
 public void checkpoint(Checkout.Order order){jdbc.update("UPDATE orders SET body=?::jsonb WHERE id=?",encode(order),order.id);}
 @Transactional public void finish(Checkout.Order order){
  jdbc.update("UPDATE orders SET body=?::jsonb,http_status=? WHERE id=?",encode(order),order.httpStatus,order.id);
  if("confirmed".equals(order.status)){
   String eventId="order-confirmed-"+order.id;
   var event=Map.of("eventId",eventId,"orderId",order.id,"customerEmail",order.customerEmail,"totalCents",order.totalCents,"trackingNumber",order.trackingNumber);
   jdbc.update("INSERT INTO order_outbox(event_id,payload) VALUES(?,?::jsonb) ON CONFLICT DO NOTHING",eventId,encode(event));
  }
 }
 public boolean healthy(){return Integer.valueOf(1).equals(jdbc.queryForObject("SELECT 1",Integer.class));}
}

package com.commercelens.orders;

import org.springframework.amqp.core.*;
import org.springframework.amqp.rabbit.connection.CorrelationData;
import org.springframework.amqp.rabbit.core.RabbitTemplate;
import org.springframework.context.annotation.Bean;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import org.springframework.transaction.support.TransactionTemplate;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.concurrent.TimeUnit;

@Component
public class OutboxPublisher {
 private final JdbcTemplate jdbc;private final RabbitTemplate rabbit;private final TransactionTemplate transaction;
 public OutboxPublisher(JdbcTemplate jdbc,RabbitTemplate rabbit,TransactionTemplate transaction){this.jdbc=jdbc;this.rabbit=rabbit;this.transaction=transaction;}
 @Bean public Queue orderQueue(){return new Queue("order.confirmed",true,false,false,Map.of("x-dead-letter-exchange","","x-dead-letter-routing-key","order.confirmed.dead"));}
 @Bean public Queue deadQueue(){return new Queue("order.confirmed.dead",true);}
 @Scheduled(fixedDelay=2000) public void publish(){
  // At-least-once delivery: consumers deduplicate eventId. Never lose an event on broker outage.
  transaction.executeWithoutResult(status->{
   var rows=jdbc.queryForList("SELECT event_id,payload::text AS payload FROM order_outbox WHERE published_at IS NULL ORDER BY created_at LIMIT 10 FOR UPDATE SKIP LOCKED");
   for(var row:rows){String id=(String)row.get("event_id");try{
    var props=new MessageProperties();props.setContentType("application/json");props.setDeliveryMode(MessageDeliveryMode.PERSISTENT);props.setMessageId(id);
    var correlation=new CorrelationData(id);
    rabbit.send("","order.confirmed",new Message(((String)row.get("payload")).getBytes(StandardCharsets.UTF_8),props),correlation);
    var confirm=correlation.getFuture().get(5,TimeUnit.SECONDS);
    if(!confirm.isAck()||correlation.getReturned()!=null)throw new IllegalStateException("broker did not confirm routed message");
    jdbc.update("UPDATE order_outbox SET published_at=now(),attempts=attempts+1,last_error=NULL WHERE event_id=?",id);
   }catch(Exception e){if(e instanceof InterruptedException)Thread.currentThread().interrupt();jdbc.update("UPDATE order_outbox SET attempts=attempts+1,last_error=? WHERE event_id=?",e.getClass().getSimpleName(),id);break;}}
  });
 }
}

package com.commercelens.orders;

import com.fasterxml.jackson.annotation.JsonIgnore;
import java.time.Instant;
import java.util.*;

/** Checkout saga. External effects are never retried blindly after uncertain outcomes. */
public class Checkout {
 public record Item(String sku,int quantity) {}
 public record Request(String customerEmail,String postalCode,List<Item> items,String paymentScenario,String shippingScenario) {}
 public record Reservation(List<Map<String,Object>> items,long subtotalCents) {}
 public static class Order {
  public String id,status,customerEmail,postalCode,paymentId,trackingNumber,failureReason,createdAt;
  public List<Map<String,Object>> items=List.of();
  public long subtotalCents,shippingCents=500,totalCents;
  @JsonIgnore public int httpStatus=409;
  public Order() {}
  public Order(String id,Request req){this.id=id;status="pending";customerEmail=req.customerEmail();postalCode=req.postalCode();createdAt=Instant.now().toString();}
 }
 public interface Ports {
  Reservation reserve(String orderId,Request request);
  String pay(String orderId,long cents,String scenario);
  String ship(String orderId,String postalCode,String scenario);
  void release(String orderId);
  void refund(String paymentId,String orderId);
  default void checkpoint(Order order) {}
 }
 public static class RemoteFailure extends RuntimeException {public final int status;public RemoteFailure(int status,String message){super(message);this.status=status;}}
 private final Ports ports;
 public Checkout(Ports ports){this.ports=ports;}
 public static void validate(Request r){
  if(r==null||r.customerEmail()==null||r.customerEmail().length()>254||!r.customerEmail().matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$")||r.postalCode()==null||!r.postalCode().matches("^[A-Za-z0-9 -]{3,16}$"))throw new IllegalArgumentException("valid customerEmail and postalCode are required");
  if(r.items()==null||r.items().isEmpty()||r.items().size()>100)throw new IllegalArgumentException("1-100 items required");
  Set<String> seen=new HashSet<>();for(Item item:r.items()){if(item==null||item.sku()==null||!item.sku().matches("^[A-Za-z0-9_-]{1,100}$")||item.quantity()<1||item.quantity()>1000||!seen.add(item.sku()))throw new IllegalArgumentException("distinct SKUs with quantities between 1 and 1000 required");}
  if(r.paymentScenario()!=null&&!Set.of("success","decline","timeout").contains(r.paymentScenario()))throw new IllegalArgumentException("invalid payment scenario");
  if(r.shippingScenario()!=null&&!Set.of("success","failure").contains(r.shippingScenario()))throw new IllegalArgumentException("invalid shipping scenario");
 }
 public Order run(String id,Request request){return run(new Order(id,request),request);}
 public Order run(Order order,Request request){
  Reservation reservation;
  try {reservation=ports.reserve(order.id,request);}catch(RemoteFailure e){order.status=e.status>=500?"manual_review":"failed";order.failureReason="Inventory reservation: "+e.getMessage();order.httpStatus=e.status>=500?503:e.status;return order;}
  order.items=reservation.items();order.subtotalCents=reservation.subtotalCents();order.totalCents=order.subtotalCents+order.shippingCents;order.status="reserved";ports.checkpoint(order);
  // Persist uncertainty before sending a payment: a crash cannot be mistaken for no charge.
  order.status="payment_unknown";ports.checkpoint(order);
  try {order.paymentId=ports.pay(order.id,order.totalCents,Objects.requireNonNullElse(request.paymentScenario(),"success"));}
  catch(RemoteFailure e){order.failureReason="Payment: "+e.getMessage();order.httpStatus=e.status>=500?504:e.status;if(e.status!=402){order.status="payment_unknown";return order;}order.status="failed";release(order);return order;}
  order.status="paid";ports.checkpoint(order);
  try {order.trackingNumber=ports.ship(order.id,request.postalCode(),Objects.requireNonNullElse(request.shippingScenario(),"success"));}
  catch(RemoteFailure e){
   order.failureReason="Shipping: "+e.getMessage();order.httpStatus=502;
   // A transport timeout can mean the carrier accepted the shipment; retain resources for review.
   if(e.status>=500){order.status="manual_review";return order;}
   order.status="failed";
   try{ports.refund(order.paymentId,order.id);}catch(RuntimeException refund){order.status="manual_review";order.failureReason+="; refund requires reconciliation";}
   release(order);return order;
  }
  order.status="confirmed";order.httpStatus=201;return order;
 }
 private void release(Order order){try{ports.release(order.id);}catch(RuntimeException release){order.status="manual_review";order.failureReason+="; stock release requires reconciliation";order.httpStatus=503;}}
}

